 * @dev Implementation of the ERC-4626 "Tokenized Vault Standard" as defined in
 * https://eips.ethereum.org/EIPS/eip-4626[ERC-4626].
 *
 * This extension allows the minting and burning of "shares" (represented as ERC-20) in exchange for
 * underlying "assets" through standardized {deposit}, {mint}, {withdraw}, and {redeem} mechanics.
 *
 * This contract extends the ERC-20 standard. Any additional extensions included along it, will be
 * applied to the ERC-20 token represented by the shares.
 */
abstract contract ERC4626 is ERC20, IERC4626, IERC20Errors {
    using SafeERC20 for IERC20;
    using Math for uint256;

    IERC20 private immutable _asset;
    uint8 private immutable _underlyingDecimals;

