    using Math for uint256;

    IERC20 private immutable _asset;
    uint8 private immutable _underlyingDecimals;

    /**
     * @dev Set the underlying asset contract. This must be an ERC-20 compatible contract.
     */
    constructor(IERC20 asset_) {
        (bool ok, uint8 assetDecimals) = _tryGetAssetDecimals(asset_);
        _underlyingDecimals = ok ? assetDecimals : 18;
        _asset = asset_;
    }

    /**
     * @dev Attempts to retrieve the decimals of an ERC-20 token via a static call.
     * If the call succeeds, returns true and the decimals value.
     * If the call fails or the value is out of range, returns false and 0.
     */
    function _tryGetAssetDecimals(IERC20 asset_) private view returns (bool ok, uint8 assetDecimals) {
        (bool success, bytes memory data) = address(asset_).staticcall(abi.encodeCall(IERC20Metadata.decimals, ()));
        if (success && data.length >= 32) {
            uint256 decoded = abi.decode(data, (uint256));
            if (decoded <= type(uint8).max) {
                return (true, uint8(decoded));
            }
        }
        return (false, 0);
    }

    /**
     * @dev Returns the number of decimals the token uses.
     * The decimals of the vault token equals the sum of the underlying asset's decimals and the
     * vault's decimal offset.
